<script setup lang="ts">
import { ref } from 'vue'
import { stages, lessons } from '../data/content'
import { useNavigation } from '../stores/navigation'
import AppIcon from './AppIcon.vue'
withDefaults(defineProps<{ expanded?: boolean; completed?: string[] }>(), { expanded: false, completed: () => [] })
const open = ref<number[]>([1])
const nav = useNavigation()
function toggle(id:number) { open.value = open.value.includes(id) ? open.value.filter(x => x!==id) : [...open.value,id] }
function inStage(id:number) { return lessons.filter(l=>l.stageId===id) }
</script>
<template><section class="card learning-card"><div class="section-header"><h2>Jalur belajar</h2><span class="muted text-sm">6 tahap, dari nol</span></div><div v-for="stage in stages" :key="stage.id" class="stage-group"><button class="stage-row stage-button" :aria-expanded="expanded && open.includes(stage.id)" @click="expanded ? toggle(stage.id) : nav.go('path')"><span class="stage-number" :class="{current:stage.id===1}">{{stage.id}}</span><div class="stage-copy"><h3>{{stage.title}}</h3><p>{{stage.description}}</p><div class="progress-track" role="progressbar" :aria-label="`Progres ${stage.title}`" :aria-valuenow="Math.round(inStage(stage.id).filter(l=>completed.includes(l.id)).length / stage.topics.length*100)" aria-valuemin="0" aria-valuemax="100"><span :style="{width:(inStage(stage.id).filter(l=>completed.includes(l.id)).length / stage.topics.length*100)+'%'}"></span></div></div><span class="stage-percent">{{inStage(stage.id).some(l=>completed.includes(l.id)) ? `${inStage(stage.id).filter(l=>completed.includes(l.id)).length}/${stage.topics.length} selesai` : 'Belum mulai'}}</span><AppIcon name="chevron" :size="15"/></button><div v-if="expanded && open.includes(stage.id)" class="lesson-list"><div v-for="(topic,i) in stage.topics" :key="topic" class="lesson-list-item"><div><strong>{{topic}}</strong><p class="muted text-sm">{{inStage(stage.id)[i] ? `${inStage(stage.id)[i]!.minutes} menit · ${completed.includes(inStage(stage.id)[i]!.id) ? 'Selesai' : 'Perlu ditinjau guru'}` : 'Materi disiapkan'}}</p></div><button v-if="inStage(stage.id)[i]" class="button secondary" @click="nav.go('lesson',inStage(stage.id)[i]!.id)">{{completed.includes(inStage(stage.id)[i]!.id) ? 'Baca lagi' : lessons.findIndex(l=>l.id===inStage(stage.id)[i]!.id)===0 || completed.includes(lessons[lessons.findIndex(l=>l.id===inStage(stage.id)[i]!.id)-1]?.id || '') ? 'Mulai' : 'Lompati urutan'}}<AppIcon name="arrow" :size="14"/></button><span v-else class="badge neutral">Segera hadir</span></div></div></div></section></template>
